import{_ as e,p as a,q as i,Y as s}from"./framework-e1bed10d.js";const l={},n=s(`<h1 id="_03基本语法" tabindex="-1"><a class="header-anchor" href="#_03基本语法" aria-hidden="true">#</a> 03基本语法</h1><h2 id="ddl语句" tabindex="-1"><a class="header-anchor" href="#ddl语句" aria-hidden="true">#</a> DDL语句</h2><p>数据库定义语言，用于创建和删除数据库、表、字段</p><h3 id="数据库操作" tabindex="-1"><a class="header-anchor" href="#数据库操作" aria-hidden="true">#</a> 数据库操作</h3><ul><li>查询所有数据库: show databases</li><li>查询当前使用的数据库：select database()</li><li>创建数据库：create database [if not exists] 数据库名 [default charset 字符集] [default collate 字符集排序规则]</li><li>删除数据库：drop database [if exists] 数据库名</li><li>使用数据库：use 数据库名</li></ul><h3 id="表操作" tabindex="-1"><a class="header-anchor" href="#表操作" aria-hidden="true">#</a> 表操作</h3><ul><li>创建表：create table 表名(字段1 字段1类型 [约束] [comment 字段1注释 ],字段2 字段2类型 [约束] [comment 字段2注释 ],......字段n 字段n类型 [约束] [comment 字段n注释 ]) [ comment 表注释 ] ;</li><li>创建包含外键的表：create table 表名(字段名 字段类型 字段约束 字段注释, ..., [constraint] [外键名称] foreign key (外键字段名) references 主表 主表(字段名))</li><li>删除表：drop table [if exists] 表名;</li><li>修改表名: rename table 表名 to 新表名;</li><li>查询表结构：desc 表名;</li><li>查询所有的表: show tables;</li><li>查询建表语句：show create table 表名;</li></ul><h3 id="字段操作" tabindex="-1"><a class="header-anchor" href="#字段操作" aria-hidden="true">#</a> 字段操作</h3><ul><li>添加字段：alter table 表名 add 字段名称 字段类型(长度) [comment 注释] [约束]</li><li>添加字段外键约束： alter table 表名 add [constraint] [外键名称] foreign key (外键字段名) references 主表 主表(字段名))</li><li>修改字段类型：alter table 表名 modify 字段名称 字段类型(长度) [comment 注释] [约束]</li><li>修改字段名称和类型：alter table 表名 change 旧名称字段 新名称字段 字段类型(长度) [comment 注释] [约束]</li><li>删除字段：alter table 表名 drop column 字段名称</li><li>删除外键：alter table 表名 drop foreign key 字段名称</li></ul><h3 id="字段约束" tabindex="-1"><a class="header-anchor" href="#字段约束" aria-hidden="true">#</a> 字段约束</h3><p>字段约束用于保证表中字段数据的正确性和完整性，是作用于字段的规则</p><ul><li>默认约束 default：如果没有指定字段的值，则使用默认值</li><li>非空约束 not null：存储在表中的字段数据不能为null</li><li>唯一约束 unique：存储在表中的字段数据必须唯一，不能重复</li><li>主键约束 primary key：存储在表中的字段数据必须唯一且不能重复，并且不能为null</li><li>自增约束 auto_increment：字段值自动增长</li><li>外键约束 foreign key：让两张表建立联系，从而保证数据的完整性和一致性</li></ul><h2 id="dml语句" tabindex="-1"><a class="header-anchor" href="#dml语句" aria-hidden="true">#</a> DML语句</h2><p>数据库操作语句，用于对数据的增删改</p><ul><li>添加表指定字段数据：insert into 表名(字段1,字段2,字段3) values（值1,值2,值3)[,(值1,值2,值3)]</li><li>添加表所有字段数据：insert into 表名 values(值1,值2,值3,...),(值1,值2,值3,...)</li><li>修改表指定字段数据：update 表名 set 字段1=值1,字段2=值2,字段3=值3 [where 条件]</li><li>删除表指定字段数据：delete from 表名 [where 条件]</li></ul><h2 id="dql语句" tabindex="-1"><a class="header-anchor" href="#dql语句" aria-hidden="true">#</a> DQL语句</h2><h3 id="基本查询" tabindex="-1"><a class="header-anchor" href="#基本查询" aria-hidden="true">#</a> 基本查询</h3><ol><li>查询所有字段：select * from 表名</li><li>查询多个字段：select 字段1,字段2[,...] from 表名</li><li>查询后设置别名 select 字段1 [as 字段1别名],字段2 from 表名</li><li>查询后去除重复值 select distinct 字段列表 from 表名</li></ol><h3 id="条件查询" tabindex="-1"><a class="header-anchor" href="#条件查询" aria-hidden="true">#</a> 条件查询</h3><p>基本语法</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token keyword">select</span> 字段列表 from 表名 where 条件列表
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>运算符：条件列表中的条件运算符主要分为比较运算符和逻辑运算符</p><p>比较运算符：</p><ul><li>&gt;, &gt;=, &lt;, &lt;=, =, !=：做相等和大小判断</li><li>between A and B：在A与B的这个范围之内</li><li>in (...)：值为in后面的列表之一</li><li>like 占位符：模糊匹配，<code>_</code>匹配单个字符；<code>%</code>匹配任意个字符，包括0个；<code>[]</code> 可以匹配集合内的字符,用脱字符<code>^</code> 可以对其进行否定</li><li>is null：值为null，不能使用<code>=null</code></li><li>is not null：值不为null</li></ul><p>逻辑运算符：</p><ul><li>and或者&amp;&amp;：逻辑与，同时满足</li><li>or或者||；逻辑或，满足其中一个</li><li>not或者!：逻辑非，不满足条件</li></ul><h3 id="分组查询" tabindex="-1"><a class="header-anchor" href="#分组查询" aria-hidden="true">#</a> 分组查询</h3><p>分组查询语法：select 字段列表 from 表名 [where 条件列表] group by 分组字段名 [having 分组后过滤条件]</p><p>示例：select gender,count(&quot;date&quot;) as &quot;date_count&quot; from user where date &lt;= &quot;2021-12-21&quot; group by date having count(&quot;date&quot;) &gt; 10</p><p>where与having的区别：</p><ul><li>where是在分组之前使用，是对分组前的数据进行过滤，符合条件的才参与分组；having是对分组后的数据进行过滤</li><li>where不能对聚合函数进行判断，having可以</li></ul><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>聚合函数：将一列的数据作为一个整体，进行纵向计算。进行计算时，所有的null值不参与计算
count：统计查询结果的数量
min：统计某一列的最小值
max：统计某一列的最大值
avg：统计某一列的平均值
sum：统计某一列的总和
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="排序查询" tabindex="-1"><a class="header-anchor" href="#排序查询" aria-hidden="true">#</a> 排序查询</h3><p>排序查询，需要使用order by，支持两种排序方式，asc升序，desc降序，如果不写，默认为asc</p><p>基本语法：select 字段列表 from 表名 [where 条件列表] [group by 分组字段名] [having 分组后过滤条件] order by 排序字段1 [asc/desc],排序字段2 [asc/desc]...</p><h3 id="分页查询" tabindex="-1"><a class="header-anchor" href="#分页查询" aria-hidden="true">#</a> 分页查询</h3><p>分页查询中，需要使用limit，数据开始索引从0开始</p><p>基本语法为：select 字段列表 from 表名 [where 筛选条件] limit 数据开始索引，单页数量</p><h3 id="执行顺序" tabindex="-1"><a class="header-anchor" href="#执行顺序" aria-hidden="true">#</a> 执行顺序</h3><p>DQL中，语句的执行顺序为</p><p>from -&gt; where -&gt; group by -&gt; having -&gt; select -&gt; order by -&gt; limit</p><h2 id="dcl语句" tabindex="-1"><a class="header-anchor" href="#dcl语句" aria-hidden="true">#</a> DCL语句</h2><p>数据库控制语言，用于操作数据库的用户及数据库访问权限</p><h3 id="用户管理" tabindex="-1"><a class="header-anchor" href="#用户管理" aria-hidden="true">#</a> 用户管理</h3><p>查询用户</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>use mysql
<span class="token keyword">select</span> * from user
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>创建用户</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>create user <span class="token string">&#39;用户名&#39;</span>@<span class="token string">&#39;主机名&#39;</span> identified by <span class="token string">&#39;密码&#39;</span>
create user <span class="token string">&#39;用户名&#39;</span>@<span class="token string">&#39;%&#39;</span> identified by <span class="token string">&#39;密码&#39;</span> <span class="token comment"># 任意主机都可以访问</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>修改密码</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>alter user <span class="token string">&#39;用户名&#39;</span>@<span class="token string">&#39;主机名&#39;</span> identified with mysql_native_password by <span class="token string">&quot;密码&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>删除用户</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>drop user <span class="token string">&#39;用户名&#39;</span>@<span class="token string">&#39;主机名&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h3 id="权限控制" tabindex="-1"><a class="header-anchor" href="#权限控制" aria-hidden="true">#</a> 权限控制</h3><p>mysql中定义了很多种权限，常用的有以下几种：</p><ul><li>ALL：所有权限</li><li>SELECT：数据查询权限</li><li>INSERT：数据插入权限</li><li>UPDATE：数据更新权限</li><li>DELETE：数据删除权限</li><li>CREATE：创建数据库、表的权限</li><li>ALTER：修改表的权限</li><li>DROP：删除数据库、表、视图的权限</li></ul><p>查询用户拥有的权限</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>show grants <span class="token keyword">for</span> <span class="token string">&#39;用户名&#39;</span>@<span class="token string">&#39;主机名&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>授予用户权限</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>grant 权限列表 on 数据库名.表名 to <span class="token string">&#39;用户名&#39;</span>@<span class="token string">&#39;主机名&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>删除用户权限</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>revoke 权限列表 on 数据库名.表名 from <span class="token string">&#39;用户名&#39;</span>@<span class="token string">&#39;主机名&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div>`,61),d=[n];function r(t,c){return a(),i("div",null,d)}const h=e(l,[["render",r],["__file","03grammar.html.vue"]]);export{h as default};
